-- ── Query 2 ────────────────────────────────────────────────────────────
SELECT\\n    dh.DEAL_ID AS \\\"Deal ID\\\",\\n    dh.TYPE AS \\\"Deal Type\\\",\\n    dh.STATUS AS \\\"Deal Status\\\",\\n    dh.SUPPLIER AS \\\"Supplier ID\\\",\\n    s.SUP_NAME AS \\\"Supplier Name\\\",\\n    dh.CURRENCY_CODE AS \\\"Currency Code\\\",\\n    dh.ACTIVE_DATE AS \\\"Active Date\\\",\\n    dh.CLOSE_DATE AS \\\"Close Date\\\",\\n    dh.BILLING_TYPE AS \\\"Billing Type\\\",\\n    dh.BILL_BACK_PERIOD AS \\\"Bill Back Period\\\",\\n    dh.DEAL_INCOME_CALCULATION AS \\\"Deal Income Calculation\\\",\\n    dh.REBATE_IND AS \\\"Rebate Indicator\\\",\\n    dh.REBATE_CALC_TYPE AS \\\"Rebate Calculation Type\\\",\\n    dh.ACTUAL_MONIES_EARNED_TO_DATE AS \\\"Header Monies Earned\\\",\\n    dh.TURNOVER_TO_DATE AS \\\"Header Turnover\\\",\\n    dd.DEAL_DETAIL_ID AS \\\"Deal Detail ID\\\",\\n    dd.DEAL_COMP_TYPE AS \\\"Deal Component Type\\\",\\n    dd.COLLECT_START_DATE AS \\\"Collection Start Date\\\",\\n    dd.COLLECT_END_DATE AS \\\"Collection End Date\\\",\\n    dd.DEAL_CLASS AS \\\"Deal Class\\\",\\n    dd.TOTAL_FORECAST_UNITS AS \\\"Total Forecast Units\\\",\\n    dd.TOTAL_FORECAST_REVENUE AS \\\"Total Forecast Revenue\\\",\\n    dd.TOTAL_BUDGET_TURNOVER AS \\\"Total Budget Turnover\\\",\\n    dd.ACTUAL_MONIES_EARNED_TO_DATE AS \\\"Detail Monies Earned\\\",\\n    dd.TURNOVER_TO_DATE AS \\\"Detail Turnover\\\",\\n    af.REPORTING_DATE AS \\\"Reporting Date\\\",\\n    af.ACTUAL_FORECAST_IND AS \\\"Actual Forecast Indicator\\\",\\n    af.BASELINE_TURNOVER AS \\\"Baseline Turnover\\\",\\n    af.BUDGET_TURNOVER AS \\\"Budget Turnover\\\",\\n    af.BUDGET_INCOME AS \\\"Budget Income\\\",\\n    af.ACTUAL_FORECAST_TURNOVER AS \\\"Actual Forecast Turnover\\\",\\n    af.ACTUAL_FORECAST_INCOME AS \\\"Actual Forecast Income\\\",\\n    af.ACTUAL_INCOME AS \\\"Actual Income\\\",\\n    af.INVC_PROCESSED_IND AS \\\"Invoice Processed Indicator\\\",\\n    af.ACTUAL_FORECAST_INCOME - af.BUDGET_INCOME AS \\\"Income Variance\\\"FROM rds_wv_deal_head dh\\nINNER JOIN rds_wv_deal_detail dd ON dd.DEAL_ID = dh.DEAL_ID\\nINNER JOIN rds_wv_sups s ON s.SUPPLIER = dh.SUPPLIER\\nLEFT JOIN rds_wv_deal_actuals_forecast af ON af.DEAL_ID = dd.DEAL_ID AND af.DEAL_DETAIL_ID = dd.DEAL_DETAIL_ID\\nWHERE dh.STATUS NOT IN ('C', 'R')\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-06-29T08:21:09.825+0000","connection-namespace":"weblogic","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_309_Deal Income Report'","parent-namespace":"ReCommon","parent-name":"RPT_309_Deal Income Report","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_309_Deal Income Report'"}
